fn digit_value(c: Str) -> Int {
    if c == "0" {
        return 0
    }
    if c == "1" {
        return 1
    }
    if c == "2" {
        return 2
    }
    if c == "3" {
        return 3
    }
    if c == "4" {
        return 4
    }
    if c == "5" {
        return 5
    }
    if c == "6" {
        return 6
    }
    if c == "7" {
        return 7
    }
    if c == "8" {
        return 8
    }
    return 9
}

fn digit_char(d: Int) -> Str {
    if d == 0 {
        return "0"
    }
    if d == 1 {
        return "1"
    }
    if d == 2 {
        return "2"
    }
    if d == 3 {
        return "3"
    }
    if d == 4 {
        return "4"
    }
    if d == 5 {
        return "5"
    }
    if d == 6 {
        return "6"
    }
    if d == 7 {
        return "7"
    }
    if d == 8 {
        return "8"
    }
    return "9"
}

fn digits_of(s: Str) -> List[Int] {
    var out: List[Int] = []
    for c in s.chars() {
        out = out.push(digit_value(c))
    }
    return out
}

fn at(xs: List[Int], i: Int) -> Int {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return 0
        }
    }
}

pub fn add_decimal(a: Str, b: Str) -> Str {
    let da = digits_of(a)
    let db = digits_of(b)
    let la = da.len()
    let lb = db.len()
    var n = la
    if lb > n {
        n = lb
    }

    var rev: List[Int] = []
    var carry = 0
    var i = 0
    while i < n {
        var x = 0
        var y = 0
        if i < la {
            x = at(da, la - 1 - i)
        }
        if i < lb {
            y = at(db, lb - 1 - i)
        }
        let s = x + y + carry
        rev = rev.push(s - (s / 10) * 10)
        carry = s / 10
        i = i + 1
    }
    if carry > 0 {
        rev = rev.push(carry)
    }

    var out = ""
    var started = false
    var j = rev.len() - 1
    while j >= 0 {
        let d = at(rev, j)
        if d != 0 or started {
            out = out + digit_char(d)
            started = true
        }
        j = j - 1
    }
    if out == "" {
        return "0"
    }
    return out
}
